-- 创建第1个测试账本：家庭账本
INSERT INTO ledgers (name, type, createdBy, ownerId, description)
VALUES ('家庭账本', 'family', 4200293, 4200293, '家庭日常开支记录');

-- 获取刚创建的账本ID
SET @ledger1_id = LAST_INSERT_ID();

-- 为第1个账本添加所有者成员（只使用必需字段）
INSERT INTO ledger_members (ledgerId, userId, role, nickname)
VALUES (@ledger1_id, 4200293, 'owner', '胡');

-- 创建第2个测试账本：生意账本
INSERT INTO ledgers (name, type, createdBy, ownerId, description)
VALUES ('生意账本', 'business', 4200293, 4200293, '公司业务收支记录');

-- 获取第2个账本ID
SET @ledger2_id = LAST_INSERT_ID();

-- 为第2个账本添加所有者成员
INSERT INTO ledger_members (ledgerId, userId, role, nickname)
VALUES (@ledger2_id, 4200293, 'owner', '胡');

-- 查询创建的账本
SELECT l.*, COUNT(lm.id) as member_count 
FROM ledgers l 
LEFT JOIN ledger_members lm ON l.id = lm.ledgerId 
WHERE l.ownerId = 4200293 
GROUP BY l.id;

